const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const MAP = {
  open:'email_open', opened:'email_open', open_event:'email_open', email_open:'email_open', email_opened:'email_open',
  click:'email_click', clicked:'email_click', click_event:'email_click', link_click:'email_click', email_click:'email_click', email_clicked:'email_click', email_link_click:'email_click',
  reply:'email_reply', replied:'email_reply', reply_event:'email_reply', email_reply:'email_reply', email_replied:'email_reply', reply_received:'email_reply', inbound_reply:'email_reply', message_reply:'email_reply'
};
const toIso = (t) => {
  if (t == null || t === '') return new Date().toISOString();
  if (typeof t === 'number' || /^\d+(\.\d+)?$/.test(String(t))) {
    let n = Number(t);
    if (n < 1e12) n = n * 1000;
    const d = new Date(n);
    return isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
  }
  const d = new Date(t);
  return isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
};
const utmFrom = (u) => {
  if (!u) return '';
  const m = String(u).match(/[?&]utm_campaign=([^&#]+)/i);
  if (!m) return '';
  try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }
};
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const b = (j.body && typeof j.body === 'object') ? j.body : j;
  const events = Array.isArray(b) ? b : (Array.isArray(b.events) ? b.events : (b['event-data'] ? [b['event-data']] : [b]));
  for (const ev of events) {
    if (!ev || typeof ev !== 'object') continue;
    const raw = String(ev.event_type || ev.event || ev.type || ev.RecordType || ev.eventType || '').trim().toLowerCase().replace(/[\s.-]+/g, '_');
    const et = MAP[raw];
    if (!et) continue;
    const url = ev.url || ev.URL || ev.link || ev.Link || ev.OriginalLink || (ev.click && ev.click.url) || '';
    const campaign = ev.utm_campaign || ev.campaign || (ev.tracking && ev.tracking.utm_campaign) || (ev['user-variables'] && ev['user-variables'].utm_campaign) || ev.campaign_name || utmFrom(url) || '';
    const account = ev.account || '';
    const contact = ev.email || ev.recipient || ev.Recipient || ev.to || ev.to_email || ev.lead_email || ev.contact || (ev.envelope && ev.envelope.to) || '';
    const eventId = ev.event_id || ev.sg_event_id || ev.stats_id || ev.id || ev.MessageID || ev.message_id || '';
    const occurred = toIso(ev.occurred_at || ev.timestamp || ev.ReceivedAt || ev.DeliveredAt || ev.created_at || ev.time || ev.event_timestamp || '');
    const value = (ev.value != null && ev.value !== '') ? Number(ev.value) : 1;
    const meta = { email_event_id: String(eventId), raw_event: String(ev.event_type || ev.event || ev.type || ev.RecordType || ev.eventType || ''), tool: String(ev.tool || ev.source || 'email') };
    if (et === 'email_click' && url) meta.url = String(url).slice(0, 400);
    if (et === 'email_reply' && (ev.reply_body || ev.reply_message)) meta.reply_snippet = String(ev.reply_body || ev.reply_message).slice(0, 200);
    out.push({ json: {
      account_esc: esc(account),
      contact_esc: esc(contact),
      campaign_esc: esc(campaign),
      event_type: et,
      event_id_esc: esc(eventId),
      value: Number.isFinite(value) ? value : 1,
      occurred_esc: esc(occurred),
      metadata_esc: esc(JSON.stringify(meta))
    } });
  }
}
return out;
